const AIR_CURTAIN_INDEX=['Company Profile','Trade License','Certificates','Compliance Statement','Material Schedule','Air Curtain Datasheets','Technical Drawings','Installation Details','Performance Data','Test Reports','Warranty Certificate','Country of Origin','Project Reference List'].join('\n');
const PQ_FAN_INDEX=['Prequalification Letter','Company Profile','Trade License','Organization Chart','Quality & HSE Policies','Certificates','Authorization Letter','KVF-P Catalogue','KVF-M Catalogue','KVF-MR Catalogue','KIN-E Catalogue','KTAF Catalogue','Test Certificates','Approval Copies','Project Reference List'].join('\n');
const PQ_AIR_CURTAIN_INDEX=['Prequalification Letter','Company Profile','Trade License','Organization Chart','Quality & HSE Policies','Certificates','Authorization Letter','N-Cross Flow Catalogue','N-Centrifugal Flow Catalogue','XD-Centrifugal Flow Catalogue','Test Certificates','Approval Copies','Project Reference List'].join('\n');
const OM_FAN_INDEX=['O&M Cover Letter','Approved Material Submittal','Approved Material Schedule','KVF-P O&M Manual','KVF-M O&M Manual','KVF-MR O&M Manual','KIN-E O&M Manual','KTAF O&M Manual','Product Catalogues','Datasheets & Performance Curves','Technical Drawings','Installation Instructions','Operation Instructions','Maintenance Schedule','Test Certificates','Warranty Certificates','Spare Parts List','Contact Details'].join('\n');
const OM_AIR_CURTAIN_INDEX=['O&M Cover Letter','Approved Material Submittal','Approved Material Schedule','N-Cross Flow O&M Manual','N-Centrifugal Flow O&M Manual','XD-Centrifugal Flow O&M Manual','Product Catalogues','Datasheets','Technical Drawings','Installation Instructions','Operation Instructions','Maintenance Schedule','Test Certificates','Warranty Certificates','Spare Parts List','Contact Details'].join('\n');
const AIR_HANDLING_INDEX=['Company Profile','Trade License','Certificates','Compliance Statement','Equipment Schedule','Selection Data','Unit Datasheets','Certified Technical Drawings','Fan & Motor Data','Coil Selection','Filter Data','Acoustic Data','Control Sequence','Installation Requirements','Test Reports','Warranty Certificate','Country of Origin','Project Reference List'].join('\n');
const ECOLOGY_INDEX=['Company Profile','Trade License','Certificates','Compliance Statement','Equipment Schedule','Selection Data','Unit Datasheets','Certified Technical Drawings','ESP Cell Data','Filtration Stages','Fan & Motor Data','Control Sequence','Installation Requirements','Test Reports','Warranty Certificate','Country of Origin','Project Reference List'].join('\n');
const SERIES=[{name:'KVF-P',brand:'KINAIR',family:'Fan'},{name:'KVF-M',brand:'KINAIR',family:'Fan'},{name:'KVF-MR',brand:'KINAIR',family:'Fan'},{name:'KIN-E',brand:'KINAIR',family:'Fan'},{name:'KTAF',brand:'KINAIR',family:'Fan'},{name:'N-Cross Flow',brand:'KINAIR',family:'Air Curtain'},{name:'N-Centrifugal Flow',brand:'KINAIR',family:'Air Curtain'},{name:'XD-Centrifugal Flow',brand:'KINAIR',family:'Air Curtain'},{name:'VVS',brand:'VTS Clima',family:'AHU / FAHU / MAHU / Ecology'},{name:'WING',brand:'VTS Clima',family:'Air Curtain'}] as const;
const PRESETS=[
 {name:'Standard Material',type:'regular' as const,brand:'KINAIR',material:'Material Submittal',index:DEFAULT_INDEXES.regular},
 {name:'KINAIR Fan',type:'regular' as const,brand:'KINAIR',material:'Ventilation Fans',series:['KVF-P','KVF-M','KVF-MR','KIN-E','KTAF'],index:FAN_INDEX},
 {name:'KINAIR Air Curtain',type:'regular' as const,brand:'KINAIR',material:'Air Curtain Units',series:['N-Cross Flow','N-Centrifugal Flow','XD-Centrifugal Flow'],index:AIR_CURTAIN_INDEX},
 {name:'VTS Clima Air Curtain',type:'regular' as const,brand:'VTS Clima',material:'Air Curtain Units',series:['WING'],index:AIR_CURTAIN_INDEX},
 {name:'VTS Clima AHU',type:'regular' as const,brand:'VTS Clima',material:'Air Handling Units (AHU)',series:['VVS'],index:AIR_HANDLING_INDEX},
 {name:'VTS Clima FAHU',type:'regular' as const,brand:'VTS Clima',material:'Fresh Air Handling Units (FAHU)',series:['VVS'],index:AIR_HANDLING_INDEX},
 {name:'VTS Clima MAHU',type:'regular' as const,brand:'VTS Clima',material:'Make-up Air Handling Units (MAHU)',series:['VVS'],index:AIR_HANDLING_INDEX},
 {name:'VTS Clima Ecology',type:'regular' as const,brand:'VTS Clima',material:'Ecology Units',series:['VVS'],index:ECOLOGY_INDEX},
 {name:'KINAIR Fan PQ',type:'pq' as const,brand:'KINAIR',material:'Fan Prequalification',series:['KVF-P','KVF-M','KVF-MR','KIN-E','KTAF'],coverMode:'pq_letter',index:PQ_FAN_INDEX},
 {name:'KINAIR Air Curtain PQ',type:'pq' as const,brand:'KINAIR',material:'Air Curtain Prequalification',series:['N-Cross Flow','N-Centrifugal Flow','XD-Centrifugal Flow'],coverMode:'pq_letter',index:PQ_AIR_CURTAIN_INDEX},
 {name:'KINAIR Fan O&M',type:'om' as const,brand:'KINAIR',material:'Fan Operation & Maintenance Manual',series:['KVF-P','KVF-M','KVF-MR','KIN-E','KTAF'],index:OM_FAN_INDEX},
 {name:'KINAIR Air Curtain O&M',type:'om' as const,brand:'KINAIR',material:'Air Curtain Operation & Maintenance Manual',series:['N-Cross Flow','N-Centrifugal Flow','XD-Centrifugal Flow'],index:OM_AIR_CURTAIN_INDEX},
 {name:'Company PQ',type:'pq' as const,brand:'KINAIR',material:'Company Prequalification',coverMode:'pq_letter',index:DEFAULT_INDEXES.pq},
 {name:'Standard O&M',type:'om' as const,brand:'KINAIR',material:'Operation & Maintenance Manual',index:DEFAULT_INDEXES.om},
] as const;
type IndexSection={id?:string;name:string;source_label?:string;sort_order:number};
const COVER_FIELDS=[['project_name','Project Name'],['material','Material / Submittal For'],['client_name','Client Name'],['consultant_name','MEP Consultant'],['main_contractor_name','Main Contractor'],['subcontractor_name','MEP Contractor'],['supplier_name','Supplier Name'],['brand_name','Brand Name']] as const;
const PACKAGE_COLUMNS=new Set(['project_name','material','client_name','consultant_name','main_contractor_name','subcontractor_name']);
const packageCover=(p:any)=>Object.fromEntries(COVER_FIELDS.map(([key])=>[key,p?.cover_details?.[key]??p?.[key]??(key==='supplier_name'?'KINETICS MIDDLE EAST LLC':key==='brand_name'?'KINAIR':'')]));
const packageLabels=(p:any)=>Object.fromEntries(COVER_FIELDS.map(([key,label])=>[key,p?.cover_details?.field_labels?.[key]??label]));
const packageAdditional=(p:any)=>(Array.isArray(p?.cover_details?.additional_fields)?p.cover_details.additional_fields:[]).map((x:any)=>`${x.label||''}: ${x.value||''}`).join('\n');
const packageTemplates=(p:any)=>({cover:p?.cover_details?.template_ids?.cover||'',index:p?.cover_details?.template_ids?.index||'',divider:p?.cover_details?.template_ids?.divider||'',logo:p?.cover_details?.template_ids?.logo||''});
const parseAdditional=(value:string)=>value.split(/\r?\n/).map(line=>{const split=line.indexOf(':');return split<0?{label:line.trim(),value:''}:{label:line.slice(0,split).trim(),value:line.slice(split+1).trim()}}).filter(x=>x.label);
const inferSeries=(value:string)=>{const v=value.toUpperCase();if(v.includes('KVF-MR'))return 'KVF-MR';if(v.includes('KVF-P'))return 'KVF-P';if(v.includes('KVF-M'))return 'KVF-M';if(v.includes('KIN-E'))return 'KIN-E';if(v.includes('KTAF'))return 'KTAF';if(v.includes('WING'))return 'WING';if(v.includes('VVS'))return 'VVS';if(v.includes('N-CENTRIFUGAL'))return 'N-Centrifugal Flow';if(v.includes('N-CROSS'))return 'N-Cross Flow';if(v.includes('XD-CENTRIFUGAL')||v.includes('XD'))return 'XD-Centrifugal Flow';if(v.includes('FM35')||v.includes('FM45')||v.includes('FM55'))return 'XD-Centrifugal Flow';if(v.includes('FM-12')||v.includes('N-2'))return 'N-Cross Flow';return ''};
const normalize=(v:string)=>v.toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').trim();
const aliases:Record<string,string[]>={
 'company profile':['company profile'],
 'trade license':['trade license','commercial license'],
 'certificates':['certificates','certificate','ce certificate','cb certificate'],
 'authorization letter':['authorization letter','authorisation letter'],
 'project specification':['project specification','specification'],
 'compliance statement':['compliance statement','compliance statment'],
 'list of materials boq':['list of materials','boq','material schedule','equipment schedule'],
 'product catalogue':['product catalogue','product catalog','catalogue','catalog','product data','technical data','datasheet'],
 'test reports':['test reports','test report'],
 'method statement':['method statement','method statment'],
 'estidama form':['estidama','sustainability'],
 'warranty certificate':['warranty certificate','warranty'],
 'country of origin':['country of origin','origin certificate'],
 'previous material approvals project list':['previous material approvals','previous approvals','project list','reference projects'],
};
const canonical=(name:string)=>{const n=normalize(name);return Object.entries(aliases).find(([,terms])=>terms.some(t=>n.includes(normalize(t))||normalize(t).includes(n)))?.[0]||n};
const parseIndex=(value:string):IndexSection[]=>value.split(/\r?\n/).map(v=>v.replace(/^\s*\d+[.)-]?\s*/,'').replace(/\s+\d+\s*$/,'').trim()).filter(Boolean).map((name,sort_order)=>({id:crypto.randomUUID(),name,source_label:name,sort_order}));

export function AdvancedSubmittalBuilder(){
 const {user,tenantId}=useAuth();const {toast}=useToast();const qc=useQueryClient();
 const [packageId,setPackageId]=useState('');const [scheduleResult,setScheduleResult]=useState<any>(null);const [chosenSeries,setChosenSeries]=useState<Set<string>>(new Set());const [autosaveReady,setAutosaveReady]=useState(false);const [packageType,setPackageType]=useState<'regular'|'pq'|'om'>('regular');const [sourceText,setSourceText]=useState('');const [templateIds,setTemplateIds]=useState<Record<'cover'|'index'|'divider'|'logo',string>>({cover:'',index:'',divider:'',logo:''});const [dragIndex,setDragIndex]=useState<number|null>(null);const [newSection,setNewSection]=useState('');const [indexText,setIndexText]=useState(DEFAULT_INDEX);const [coverDetails,setCoverDetails]=useState<Record<string,string>>({});const [coverLabels,setCoverLabels]=useState<Record<string,string>>(Object.fromEntries(COVER_FIELDS));const [additionalFieldsText,setAdditionalFieldsText]=useState('');const [loadedVersion,setLoadedVersion]=useState(1);const [selectedModels,setSelectedModels]=useState<Set<string>>(new Set());const [result,setResult]=useState<any>(null);const [coverFieldOrder,setCoverFieldOrder]=useState<string[]>(COVER_FIELDS.map(([key])=>key));const [dragCoverIndex,setDragCoverIndex]=useState<number|null>(null);const [dropIndex,setDropIndex]=useState<number|null>(null);const [packageSearch,setPackageSearch]=useState('');const [previewSection,setPreviewSection]=useState('');
 const packages=useQuery({queryKey:['advanced-submittal-packages',tenantId],enabled:!!tenantId,queryFn:async()=>{const {data,error}=await db.from('submittal_packages').select('*').eq('tenant_id',tenantId).order('created_at',{ascending:false});if(error)throw error;return data??[]}});
 const templates=useQuery({queryKey:['submittal_templates',tenantId],enabled:!!tenantId,queryFn:async()=>{const {data,error}=await db.from('submittal_templates').select('*').eq('tenant_id',tenantId).order('created_at',{ascending:false});if(error)throw error;return data??[]}});
 const products=useQuery({queryKey:['advanced-submittal-products',tenantId],enabled:!!tenantId,queryFn:async()=>{const {data,error}=await db.from('submittal_products').select('id,name,submittal_product_models(id,name,code)').eq('tenant_id',tenantId).order('name');if(error)throw error;return data??[]}});
 const templatePreviewUrls=useQuery({queryKey:['submittal-template-previews',tenantId,templateIds],enabled:!!tenantId&&!!templates.data&&Object.values(templateIds).some(Boolean),queryFn:async()=>{const entries=await Promise.all((['cover','index','divider','logo'] as const).map(async type=>{const row=(templates.data??[]).find((t:any)=>t.id===templateIds[type]);if(!row)return [type,''];const {data}=await db.storage.from(BUCKET).createSignedUrl(row.storage_path,3600);return [type,data?.signedUrl||'']}));return Object.fromEntries(entries) as Record<'cover'|'index'|'divider'|'logo',string>}});
 const selectedPackage=packages.data?.find((p:any)=>p.id===packageId);
 const filteredPackages=useMemo(()=>{const q=normalize(packageSearch);return (packages.data??[]).filter((p:any)=>!q||normalize([p.reference,p.project_name,p.material,p.package_type].filter(Boolean).join(' ')).includes(q))},[packages.data,packageSearch]);
 const selectedTemplateNames=useMemo(()=>Object.fromEntries((['cover','index','divider','logo'] as const).map(type=>[type,(templates.data??[]).find((t:any)=>t.id===templateIds[type])?.display_name||`KINAIR standard ${type}`])) as Record<'cover'|'index'|'divider'|'logo',string>,[templates.data,templateIds]);
 const modelMap=useMemo(()=>new Map((products.data??[]).flatMap((p:any)=>p.submittal_product_models.map((m:any)=>[m.id,{...m,product_id:p.id,product_name:p.name,series:inferSeries([m.code,m.name,p.name].filter(Boolean).join(' '))}]))),[products.data]);

 function choosePackage(id:string){if(!id){setPackageId('');setSelectedModels(new Set());setResult(null);return}setPackageId(id);const p=packages.data?.find((x:any)=>x.id===id);setPackageType(p?.package_type||'regular');setCoverDetails(packageCover(p));setCoverLabels(packageLabels(p));setCoverFieldOrder(Array.isArray(p?.cover_details?.field_order)?p.cover_details.field_order:COVER_FIELDS.map(([key])=>key));setAdditionalFieldsText(packageAdditional(p));setTemplateIds(packageTemplates(p));setChosenSeries(new Set(Array.isArray(p?.cover_details?.selected_series)?p.cover_details.selected_series:[]));setLoadedVersion(p?.version||1);if(Array.isArray(p?.index_sections)&&p.index_sections.length)setIndexText(p.index_sections.map((x:any)=>x.name).join('\n'));else setIndexText(DEFAULT_INDEX);setResult(p?.validation_report?.assembly||null);void loadSelections(id)}
 async function loadSelections(id:string){const {data}=await db.from('submittal_package_products').select('model_id').eq('package_id',id);setSelectedModels(new Set((data??[]).map((x:any)=>x.model_id).filter(Boolean)))}
 function beginType(type:'regular'|'pq'|'om'){setPackageId('');setPackageType(type);setCoverDetails({supplier_name:'KINETICS MIDDLE EAST LLC',brand_name:'KINAIR',material:type==='om'?'Operation & Maintenance Manual':type==='pq'?'Prequalification':'Material Submittal',cover_mode:type==='pq'?'pq_letter':'cover'});setCoverLabels(Object.fromEntries(COVER_FIELDS));setCoverFieldOrder(COVER_FIELDS.map(([key])=>key));setAdditionalFieldsText('');setTemplateIds({cover:'',index:'',divider:'',logo:''});setChosenSeries(new Set());setSelectedModels(new Set());setScheduleResult(null);setSourceText('');setIndexText(DEFAULT_INDEXES[type]);setResult(null)}
 function applyPreset(p:(typeof PRESETS)[number]){beginType(p.type);setCoverDetails({supplier_name:'KINETICS MIDDLE EAST LLC',brand_name:p.brand,material:p.material,cover_mode:'coverMode' in p?p.coverMode:'cover'});setChosenSeries(new Set('series' in p?p.series:[]));setIndexText(p.index);toast({title:p.name+' ready',description:'Add the customer details or schedule, then build the entire package.'})}
 function moveSection(from:number,to:number){if(from===to||from<0||to<0)return;const rows=parseIndex(indexText);const [moved]=rows.splice(from,1);rows.splice(to,0,moved);setIndexText(rows.map(x=>x.name).join('\n'));setPreviewSection(moved.name)}
 function moveCoverField(from:number,to:number){if(from===to||from<0||to<0)return;setCoverFieldOrder(prev=>{const rows=[...prev];const [moved]=rows.splice(from,1);rows.splice(to,0,moved);return rows})}
 function updateSection(i:number,value:string){const rows=parseIndex(indexText);rows[i].name=value;setIndexText(rows.map(x=>x.name).join('\n'))}
 function removeSection(i:number){setIndexText(parseIndex(indexText).filter((_,n)=>n!==i).map(x=>x.name).join('\n'))}
 function addSection(){const name=newSection.trim();if(!name)return;setIndexText([...parseIndex(indexText).map(x=>x.name),name].join('\n'));setNewSection('')}
 function toggle(id:string){setSelectedModels(prev=>{const n=new Set(prev);n.has(id)?n.delete(id):n.add(id);return n})}
 async function ensurePackage(title='New submittal'){if(packageId)return packageId;if(!user||!tenantId)throw new Error('Sign in required');const sections=parseIndex(indexText);const fallbackMaterial=packageType==='om'?'O&M Manual':packageType==='pq'?'Prequalification':'Material Submittal';const material=coverDetails.material||fallbackMaterial;const initialCover={...coverDetails,field_order:coverFieldOrder,supplier_name:coverDetails.supplier_name||'KINETICS MIDDLE EAST LLC',brand_name:coverDetails.brand_name||'KINAIR',field_labels:coverLabels,additional_fields:parseAdditional(additionalFieldsText),template_ids:templateIds,selected_series:[...chosenSeries]};const {data:draft,error}=await db.from('submittal_packages').insert({tenant_id:tenantId,package_type:packageType,status:'draft',project_name:title,material,submission_date:new Date().toISOString().slice(0,10),cover_details:initialCover,index_sections:sections,created_by:user.id,updated_by:user.id}).select('*').single();if(error)throw error;setPackageId(draft.id);setCoverDetails(packageCover(draft));setCoverLabels(packageLabels(draft));setLoadedVersion(draft.version||1);await qc.invalidateQueries({queryKey:['advanced-submittal-packages']});toast({title:'Draft workspace created',description:'Your selected workflow, series and index are saved.'});return draft.id}
 function applyAnalysis(data:any){const extracted=Object.fromEntries(Object.entries(data.cover??{}).filter(([,value])=>typeof value==='string'&&value.trim()));const extractedOrder=COVER_FIELDS.map(([key])=>key).filter(key=>Object.prototype.hasOwnProperty.call(extracted,key));if(extractedOrder.length)setCoverFieldOrder([...extractedOrder,...COVER_FIELDS.map(([key])=>key).filter(key=>!extractedOrder.includes(key))]);setCoverDetails(prev=>({...prev,...extracted}));if(Array.isArray(data.cover?.additional_fields))setAdditionalFieldsText(data.cover.additional_fields.filter((x:any)=>x?.label).map((x:any)=>`${x.label}: ${x.value||''}`).join('\n'));if(data.sections?.length)setIndexText(data.sections.map((x:any)=>x.name).join('\n'));toast({title:'Cover and index read',description:`${data.sections?.length||0} sections detected. Review and edit before building.`});void qc.invalidateQueries({queryKey:['advanced-submittal-packages']})}

 const analyze=useMutation({mutationFn:async({file,targetPackageId}:{file:File;targetPackageId:string})=>{if(!user||!tenantId)throw new Error('Sign in required');if(file.size>MAX_SOURCE_BYTES)throw new Error('Cover/index file must be 250 MB or smaller');if(file.size>DIRECT_ANALYSIS_BYTES&&file.type!=='application/pdf')throw new Error('Word, Excel and PowerPoint cover/index files must be 15 MB or smaller');const path=`${tenantId}/customer-input/${targetPackageId}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'-')}`;let fileData:string;let sourceAlreadyUploaded=false;if(file.size<=DIRECT_ANALYSIS_BYTES){fileData=toBase64(new Uint8Array(await file.arrayBuffer()))}else{await resumableUpload(file,path);sourceAlreadyUploaded=true;fileData=toBase64(await makeAnalysisPdf(file))}const {data,error}=await supabase.functions.invoke('submittal-analyze',{body:{packageId:targetPackageId,storagePath:path,fileName:file.name,mimeType:file.type,fileData,sourceAlreadyUploaded}});if(error)throw error;return data},onSuccess:applyAnalysis});
 async function uploadSource(e:React.ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file||!user||!tenantId)return;try{const targetPackageId=await ensurePackage(file.name.replace(/\.[^.]+$/,'').replace(/[-_]+/g,' ').trim()||'New submittal');await analyze.mutateAsync({file,targetPackageId})}catch(x){toast({title:'Unable to read document',description:x instanceof Error?x.message:'Please retry',variant:'destructive'})}finally{e.target.value=''}}
 const analyzePasted=useMutation({mutationFn:async()=>{if(!sourceText.trim())throw new Error('Paste the customer email, cover details or index first');const targetPackageId=await ensurePackage(sourceText.trim().split(/\r?\n/)[0].slice(0,100)||'New submittal');const {data,error}=await supabase.functions.invoke('submittal-analyze',{body:{packageId:targetPackageId,sourceText:sourceText.trim()}});if(error)throw error;return data},onSuccess:applyAnalysis,onError:x=>toast({title:'Unable to read pasted details',description:x instanceof Error?x.message:'Please retry',variant:'destructive'})});
 const analyzeSchedule=useMutation({mutationFn:async(file:File)=>{if(file.size>15*1024*1024)throw new Error('Material schedule must be 15 MB or smaller');const targetPackageId=await ensurePackage(file.name.replace(/\.[^.]+$/,'').replace(/[-_]+/g,' ').trim()||'Material schedule');const availableModels=[...modelMap.values()].map((m:any)=>({id:m.id,code:m.code,name:m.name,product:m.product_name,series:m.series}));const fileData=toBase64(new Uint8Array(await file.arrayBuffer()));const {data,error}=await supabase.functions.invoke('submittal-schedule-analyze',{body:{packageId:targetPackageId,fileName:file.name,mimeType:file.type,fileData,availableModels}});if(error)throw error;return data},onSuccess:data=>{setSelectedModels(prev=>new Set([...prev,...(data.matched_model_ids??[])]));setChosenSeries(prev=>new Set([...prev,...(data.matched_series??[])]));const brands=new Set((data.matched_series??[]).map((series:string)=>SERIES.find(s=>s.name===series)?.brand).filter(Boolean));if(brands.size)setCoverDetails(prev=>({...prev,brand_name:[...brands].join(' / ')}));setScheduleResult(data);toast({title:'Material schedule matched',description:`${data.matched_model_ids?.length||0} model(s) · ${data.matched_series?.length||0} series selected`})},onError:x=>toast({title:'Schedule reading failed',description:x instanceof Error?x.message:'Please retry',variant:'destructive'})});
 async function uploadSchedule(e:React.ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return;try{await analyzeSchedule.mutateAsync(file)}finally{e.target.value=''}}

 useEffect(()=>{if(!packageId)return;const channel=supabase.channel(`submittal-workspace-${packageId}`).on('postgres_changes',{event:'UPDATE',schema:'public',table:'submittal_packages',filter:`id=eq.${packageId}`},({new:next}:any)=>{if((next.version||1)>loadedVersion){setLoadedVersion(next.version||1);setPackageType(next.package_type||'regular');setCoverDetails(packageCover(next));setCoverLabels(packageLabels(next));setCoverFieldOrder(Array.isArray(next?.cover_details?.field_order)?next.cover_details.field_order:COVER_FIELDS.map(([key])=>key));setAdditionalFieldsText(packageAdditional(next));setTemplateIds(packageTemplates(next));setChosenSeries(new Set(Array.isArray(next?.cover_details?.selected_series)?next.cover_details.selected_series:[]));if(Array.isArray(next.index_sections)&&next.index_sections.length)setIndexText(next.index_sections.map((x:any)=>x.name).join('\n'));toast({title:'Workspace updated by another user',description:'The latest cover and index are now shown.'})}}).subscribe();return()=>{void supabase.removeChannel(channel)}},[packageId,loadedVersion,toast]);

 const saveWorkspace=useMutation({mutationFn:async()=>{if(!user||!packageId)throw new Error('Select a package');const sections=parseIndex(indexText);const nextVersion=loadedVersion+1;const packageColumns=Object.fromEntries(Object.entries(coverDetails).filter(([key])=>PACKAGE_COLUMNS.has(key)));const {data,error}=await db.from('submittal_packages').update({...packageColumns,package_type:packageType,cover_details:{...coverDetails,field_order:coverFieldOrder,field_labels:coverLabels,additional_fields:parseAdditional(additionalFieldsText),template_ids:templateIds,selected_series:[...chosenSeries]},index_sections:sections,version:nextVersion,editing_by:user.id,editing_at:new Date().toISOString(),updated_by:user.id,updated_at:new Date().toISOString()}).eq('id',packageId).eq('version',loadedVersion).select('version').maybeSingle();if(error)throw error;if(!data)throw new Error('Another user changed this package. Latest values have been loaded; review and save again.');return data.version},onSuccess:version=>{setLoadedVersion(version);toast({title:'Shared workspace saved',description:'Cover, index and divider plan saved together.'})}});
 useEffect(()=>{setAutosaveReady(false);const timer=window.setTimeout(()=>setAutosaveReady(true),900);return()=>window.clearTimeout(timer)},[packageId]);
 useEffect(()=>{if(!packageId||!autosaveReady||saveWorkspace.isPending)return;const timer=window.setTimeout(()=>saveWorkspace.mutate(),1400);return()=>window.clearTimeout(timer)},[packageType,coverDetails,coverLabels,coverFieldOrder,additionalFieldsText,indexText,templateIds,chosenSeries,packageId]);

 const build=useMutation({mutationFn:async()=>{
  if(!user||!tenantId)throw new Error('Sign in required');const activePackageId=packageId||await ensurePackage(coverDetails.project_name||'New submittal');const sections=parseIndex(indexText);if(!sections.length)throw new Error('Enter at least one index section');
  const selected=[...selectedModels].map(id=>modelMap.get(id)).filter(Boolean) as any[];
  await db.from('submittal_package_products').delete().eq('package_id',activePackageId);
  if(selected.length){const {error}=await db.from('submittal_package_products').insert(selected.map(m=>({tenant_id:tenantId,package_id:activePackageId,product_id:m.product_id,model_id:m.id,created_by:user.id})));if(error)throw error}
  const {data:docs,error:docError}=await db.from('submittal_documents').select('*').eq('tenant_id',tenantId).eq('is_active',true);if(docError)throw docError;
  const {data:uploads,error:uploadError}=await db.from('submittal_attachments').select('*').eq('package_id',activePackageId).order('sort_order');if(uploadError)throw uploadError;
  const selectedProductIds=new Set(selected.map(m=>m.product_id));const selectedModelIds=new Set(selected.map(m=>m.id));const selectedSeries=new Set([...chosenSeries,...selected.map(m=>m.series).filter(Boolean)].map(normalize));
  const applicable=(d:any)=>d.scope_type==='company'||(d.scope_type==='project'&&d.package_id===packageId)||(d.scope_type==='product'&&selectedProductIds.has(d.product_id))||(d.scope_type==='model'&&selectedModelIds.has(d.model_id))||(d.scope_type==='series'&&selectedSeries.has(normalize(d.series_name||'')));
  const items:any[]=[];const summary:any[]=[];
  for(const section of sections){const rawSection=normalize(section.name);const sectionSeries=[...selectedSeries].find(series=>rawSection.includes(series));const key=canonical(section.name);const matches=(docs??[]).filter((d:any)=>{const terms=[d.category,d.display_name,...(d.keywords||[])].map((x:string)=>canonical(x||''));const correctSeries=!sectionSeries||(d.scope_type==='series'&&normalize(d.series_name||'')===sectionSeries);return applicable(d)&&correctSeries&&terms.some((x:string)=>x===key||x.includes(key)||key.includes(x))}).sort((a:any,b:any)=>Number(Boolean(b.model_id))-Number(Boolean(a.model_id))||Number(Boolean(b.product_id))-Number(Boolean(a.product_id)));const projectFiles=(uploads??[]).filter((a:any)=>canonical(a.section_name||'')===key);
   for(const d of matches){const expired=d.expires_on&&new Date(d.expires_on)<new Date();items.push({tenant_id:tenantId,package_id:activePackageId,product_id:d.product_id,model_id:d.model_id,document_id:d.id,section_name:section.name,source_type:'library',display_name:d.display_name,storage_path:d.storage_path,sort_order:items.length,is_included:true,is_required:d.is_mandatory,validation_state:expired?'expired':'ready',notes:expired?'Document expiry date has passed':null})}
   for(const file of projectFiles)items.push({tenant_id:tenantId,package_id:activePackageId,section_name:section.name,source_type:'upload',display_name:file.display_name,storage_path:file.storage_path,sort_order:items.length,is_included:true,is_required:false,validation_state:'ready'});
   const names=[...matches.map((d:any)=>d.display_name),...projectFiles.map((a:any)=>a.display_name)];if(names.length)summary.push({section:section.name,state:matches.some((d:any)=>d.expires_on&&new Date(d.expires_on)<new Date())?'warning':'ready',documents:names});else{items.push({tenant_id:tenantId,package_id:activePackageId,section_name:section.name,source_type:'generated',display_name:'Missing document',sort_order:items.length,is_included:false,is_required:true,validation_state:'missing',notes:'Upload or map a document for this section'});summary.push({section:section.name,state:'missing',documents:[]})}}
  await db.from('submittal_package_items').delete().eq('package_id',activePackageId);const {error:itemError}=await db.from('submittal_package_items').insert(items);if(itemError)throw itemError;
  const report={assembly:summary,ready:summary.filter(x=>x.state==='ready').length,missing:summary.filter(x=>x.state==='missing').length,warnings:summary.filter(x=>x.state==='warning').length,checked_at:new Date().toISOString()};
  const nextVersion=loadedVersion+1;const {data:updated,error:updateError}=await db.from('submittal_packages').update({index_sections:sections,validation_report:report,version:nextVersion,editing_by:user.id,editing_at:new Date().toISOString(),updated_by:user.id,updated_at:new Date().toISOString()}).eq('id',activePackageId).eq('version',loadedVersion).select('version').maybeSingle();if(updateError)throw updateError;if(!updated)throw new Error('Another user changed this package. Review the latest workspace and build again.');return {...report,version:updated.version};
 },onSuccess:r=>{setLoadedVersion(r.version);setResult(r.assembly);toast({title:'Automatic package prepared',description:`${r.ready} ready · ${r.missing} missing · ${r.warnings} warnings`});void qc.invalidateQueries({queryKey:['submittal-package-register']})}});

 const revise=useMutation({mutationFn:async()=>{if(!user||!tenantId||!selectedPackage)throw new Error('Select a saved package');const {error:snapshotError}=await db.from('submittal_package_revisions').insert({tenant_id:tenantId,package_id:selectedPackage.id,revision:selectedPackage.revision,snapshot:selectedPackage,created_by:user.id});if(snapshotError)throw snapshotError;const {error:updateError}=await db.from('submittal_packages').update({revision:(selectedPackage.revision||0)+1,status:'draft',approval_status:'no_update',output_storage_path:null,updated_by:user.id,updated_at:new Date().toISOString()}).eq('id',selectedPackage.id);if(updateError)throw updateError},onSuccess:()=>{toast({title:`Revision R${(selectedPackage?.revision||0)+1} created`,description:'Previous revision preserved. Add consultant comments or replace only revised documents.'});void qc.invalidateQueries({queryKey:['advanced-submittal-packages']})}});
 const generate=useMutation({mutationFn:async()=>{if((result??[]).some((x:any)=>x.state==='missing'))throw new Error('Resolve missing sections before final generation');const {data,error}=await supabase.functions.invoke('submittal-pdf',{body:{packageId}});if(error)throw error;const blob=data instanceof Blob?data:new Blob([data],{type:'application/pdf'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${selectedPackage?.reference||'submittal'}-R${selectedPackage?.revision||0}.pdf`;a.click();URL.revokeObjectURL(a.href)},onSuccess:()=>toast({title:'Final submittal generated'})});
 const counts={ready:(result??[]).filter((x:any)=>x.state==='ready').length,missing:(result??[]).filter((x:any)=>x.state==='missing').length,warning:(result??[]).filter((x:any)=>x.state==='warning').length};
 return <div className="space-y-5">
  <Card><CardHeader><CardTitle className="flex items-center gap-2"><Sparkles className="h-5 w-5 text-primary"/>Build a Complete Submittal</CardTitle><CardDescription>Choose what you need. Upload or paste the customer information and KINAIR prepares the cover or PQ letter, index, dividers and matching controlled documents in one workspace.</CardDescription></CardHeader><CardContent className="space-y-5">
   <div className="rounded-xl border bg-muted/20 p-4"><Label className="text-base">1. What do you want to make?</Label><div className="mt-3 grid gap-3 md:grid-cols-3">{([{type:'regular',title:'Material Submittal',description:'Cover page → index → dividers → technical documents'},{type:'pq',title:'PQ Submittal',description:'PQ letter → index → dividers → catalogues and approvals'},{type:'om',title:'O&M Submittal',description:'Cover → index → dividers → manuals, certificates and warranty'}] as const).map(item=><button key={item.type} type="button" onClick={()=>beginType(item.type)} className={`rounded-xl border-2 p-4 text-left transition-colors ${packageType===item.type&&!packageId?'border-primary bg-primary/5':'border-border bg-background hover:border-primary/50'}`}><span className="block text-base font-semibold">{item.title}</span><span className="mt-1 block text-sm text-muted-foreground">{item.description}</span></button>)}</div></div>
   <div className="rounded-xl border p-4"><Label className="text-base">2. Choose equipment workflow</Label><p className="mb-3 text-sm text-muted-foreground">This loads the correct standard index, series and automatic document rules.</p><div className="flex flex-wrap gap-2">{PRESETS.filter(p=>p.type===packageType).map(p=><Button key={p.name} type="button" variant="outline" onClick={()=>applyPreset(p)}>{p.name}</Button>)}</div></div>
   <div className="rounded-xl border p-4"><div className="flex flex-col gap-3 md:flex-row md:items-end"><div className="flex-1"><Label>Find or revise a saved submittal</Label><p className="mb-2 text-xs text-muted-foreground">Search by project, reference, material or submittal type.</p><Input value={packageSearch} onChange={e=>setPackageSearch(e.target.value)} placeholder="Search project or reference…"/></div><div className="flex-1"><Label>Open saved package</Label><select value={packageId} onChange={e=>choosePackage(e.target.value)} className="h-10 w-full rounded-md border bg-background px-3"><option value="">New {packageType==='regular'?'Material Submittal':packageType==='pq'?'PQ Submittal':'O&M Submittal'}</option>{filteredPackages.map((p:any)=><option key={p.id} value={p.id}>{p.reference||'Draft'} · {p.project_name}</option>)}</select></div></div>{packageSearch&&<div className="mt-3 grid gap-2 md:grid-cols-2 xl:grid-cols-3">{filteredPackages.slice(0,6).map((p:any)=><button key={p.id} type="button" onClick={()=>choosePackage(p.id)} className="rounded-lg border bg-background p-3 text-left hover:border-primary"><b className="block truncate">{p.project_name||'Untitled project'}</b><span className="block text-xs text-muted-foreground">{p.reference||'Draft'} · {p.package_type==='regular'?'Material':p.package_type==='pq'?'PQ':'O&M'} · R{p.revision||0} · {p.status}</span></button>)}{!filteredPackages.length&&<p className="text-sm text-muted-foreground">No saved submittal found.</p>}</div>}</div>
   <div className="rounded-lg border p-4"><Label>3. Paste customer email, {packageType==='pq'?'PQ letter details':'cover details'} or index</Label><p className="mb-3 text-xs text-muted-foreground">Copy from an email or document. AI fills the editable details and index. You can also skip this and enter them manually.</p><Textarea rows={6} value={sourceText} onChange={e=>setSourceText(e.target.value)} placeholder="Project: ...&#10;Client: ...&#10;Consultant: ...&#10;Index: 1. Company Profile ..."/><div className="mt-3 flex justify-end"><Button type="button" variant="secondary" disabled={!sourceText.trim()||analyzePasted.isPending} onClick={()=>analyzePasted.mutate()}>{analyzePasted.isPending&&<Loader2 className="h-4 w-4 animate-spin"/>}Read pasted details</Button></div></div>
   {packageType==='pq'?<div className="rounded-lg border border-primary/30 bg-primary/5 p-4"><b>PQ first-page rule</b><p className="mt-1 text-sm text-muted-foreground">The uploaded Prequalification Letter is the first page. No separate cover page is generated. The index and all dividers follow automatically.</p></div>:<div className="rounded-lg border p-4"><div className="mb-3 flex items-center justify-between"><div><Label>Shared cover-page details</Label><p className="text-xs text-muted-foreground">Enter manually or let AI populate these same editable fields.</p></div><span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-medium text-emerald-700">Live team sync · v{loadedVersion}</span></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">{coverFieldOrder.map((key,i)=>{const label=COVER_FIELDS.find(([field])=>field===key)?.[1]||key;return <div key={key} draggable onDragStart={()=>setDragCoverIndex(i)} onDragEnd={()=>setDragCoverIndex(null)} onDragOver={e=>e.preventDefault()} onDrop={()=>{if(dragCoverIndex!==null)moveCoverField(dragCoverIndex,i);setDragCoverIndex(null)}} className={`space-y-1 rounded-lg border p-2 transition-all duration-200 ${dragCoverIndex===i?'opacity-50 ring-2 ring-primary':'bg-background'}`}><div className="flex items-center gap-2"><GripVertical className="h-4 w-4 cursor-grab text-muted-foreground"/><Label className="text-xs text-muted-foreground">Editable label</Label></div><Input aria-label={`${label} label`} value={coverLabels[key]||label} onChange={e=>setCoverLabels(prev=>({...prev,[key]:e.target.value}))}/><Label className="text-xs text-muted-foreground">Value</Label><Input aria-label={`${label} value`} value={coverDetails[key]||''} onChange={e=>setCoverDetails(prev=>({...prev,[key]:e.target.value}))}/></div>})}</div><div className="mt-4"><Label>Additional cover fields</Label><p className="mb-2 text-xs text-muted-foreground">Optional manual fields, one per line in Label: Value format.</p><Textarea rows={3} value={additionalFieldsText} onChange={e=>setAdditionalFieldsText(e.target.value)} placeholder="Project Number: PRJ-001&#10;PMC: Example PMC"/></div></div>}
   <div className="grid gap-4 lg:grid-cols-2"><div className="rounded-lg border p-4"><Label>{packageType==='pq'?'PQ letter / index file':'Customer cover / index file'}</Label><p className="mb-3 text-xs text-muted-foreground">PDF, image, Word, Excel, PowerPoint or CSV. The system reads the details and index order automatically; no existing package is required.</p><Input type="file" accept=".pdf,image/png,image/jpeg,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.csv" disabled={analyze.isPending} onChange={uploadSource}/>{analyze.isPending&&<p className="mt-2 flex items-center gap-2 text-sm"><Loader2 className="h-4 w-4 animate-spin"/>Reading customer document…</p>}</div>
   <div className="rounded-lg border p-4"><Label>Index &amp; automatic divider order</Label><p className="mb-3 text-xs text-muted-foreground">Paste one section per line, then drag rows to arrange the final index, dividers and all documents under them.</p><Textarea rows={5} value={indexText} onChange={e=>setIndexText(e.target.value)}/><div className="mt-3 space-y-2">{parseIndex(indexText).map((section,i)=><div key={section.id} draggable onDragStart={()=>setDragIndex(i)} onDragEnd={()=>{setDragIndex(null);setDropIndex(null)}} onDragEnter={()=>setDropIndex(i)} onDragOver={e=>e.preventDefault()} onDrop={()=>{if(dragIndex!==null)moveSection(dragIndex,i);setDragIndex(null);setDropIndex(null)}} className={`flex items-center gap-2 rounded-md border bg-background p-2 shadow-sm transition-all duration-200 ${dragIndex===i?'scale-[.98] opacity-50':dropIndex===i?'border-primary ring-2 ring-primary/20':''}`}><GripVertical className="h-5 w-5 cursor-grab text-muted-foreground"/><span className="w-7 text-sm font-semibold text-primary">{i+1}</span><Input value={section.name} onChange={e=>updateSection(i,e.target.value)}/><Button type="button" size="icon" variant="ghost" onClick={()=>removeSection(i)} aria-label={`Remove ${section.name}`}><Trash2 className="h-4 w-4 text-destructive"/></Button></div>)}</div><div className="mt-3 flex gap-2"><Input value={newSection} onChange={e=>setNewSection(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();addSection()}}} placeholder="Add Consultant Comment, Reply to Consultant Comment…"/><Button type="button" variant="outline" onClick={addSection}><Plus className="h-4 w-4"/>Add section</Button></div></div></div>
   <div className="rounded-xl border p-4"><div className="mb-3"><Label className="text-base">Live page and divider preview</Label><p className="text-sm text-muted-foreground">Every index row already represents one divider. Click a divider to inspect it; changes appear immediately.</p></div><div className="grid gap-4 xl:grid-cols-[320px_1fr]"><div className="space-y-3">{packageType!=='pq'&&<div className="relative aspect-[210/297] overflow-hidden rounded-lg border bg-white shadow-sm">{templatePreviewUrls.data?.cover&&<iframe title="Cover template preview" src={templatePreviewUrls.data.cover+'#toolbar=0&navpanes=0&scrollbar=0'} className="pointer-events-none absolute inset-0 h-full w-full border-0"/>}<div className="relative z-10 h-full p-5"><div className="mb-5 border-b-4 border-primary pb-3 text-xl font-bold text-primary">KINAIR</div>{templatePreviewUrls.data?.logo&&<img src={templatePreviewUrls.data.logo} alt="Brand logo preview" className="absolute right-5 top-5 max-h-12 max-w-24 object-contain"/>}<b className="block text-lg">{coverDetails.material||'Material Submittal'}</b><div className="mt-5 space-y-2 text-xs">{coverFieldOrder.slice(0,7).map(key=><div key={key} className="grid grid-cols-[90px_1fr] gap-2 border-b pb-1"><b>{coverLabels[key]||key}</b><span>{coverDetails[key]||'—'}</span></div>)}</div><p className="mt-4 text-[11px] text-muted-foreground">{selectedTemplateNames.cover}</p></div></div>}<div className="relative overflow-hidden rounded-lg border bg-white p-4">{templatePreviewUrls.data?.index&&<iframe title="Index template preview" src={templatePreviewUrls.data.index+'#toolbar=0&navpanes=0&scrollbar=0'} className="pointer-events-none absolute inset-0 h-full w-full border-0"/>}<div className="relative z-10"><b>Index preview</b><div className="mt-2 max-h-48 space-y-1 overflow-auto">{parseIndex(indexText).map((s,i)=><div key={s.id} className="flex justify-between border-b py-1 text-xs"><span>{i+1}. {s.name}</span><span>—</span></div>)}</div><p className="mt-2 text-[11px] text-muted-foreground">{selectedTemplateNames.index}</p></div></div></div><div><div className="mb-3 flex gap-2 overflow-x-auto pb-2">{parseIndex(indexText).map((s,i)=><button key={s.id} type="button" onClick={()=>setPreviewSection(s.name)} className={`min-w-36 rounded-lg border p-3 text-left text-xs transition-colors ${(previewSection||parseIndex(indexText)[0]?.name)===s.name?'border-primary bg-primary/5':'bg-background'}`}><b className="block text-primary">{String(i+1).padStart(2,'0')}</b><span className="line-clamp-2">{s.name}</span></button>)}</div><div className="relative aspect-[297/210] overflow-hidden rounded-xl border bg-sky-50 shadow-sm">{templatePreviewUrls.data?.divider&&<iframe title="Divider template preview" src={templatePreviewUrls.data.divider+'#toolbar=0&navpanes=0&scrollbar=0'} className="pointer-events-none absolute inset-0 h-full w-full border-0"/>}<div className="absolute inset-0 border-l-[14px] border-primary p-8"><span className="text-sm font-bold text-cyan-600">{String(Math.max(1,parseIndex(indexText).findIndex(s=>s.name===(previewSection||parseIndex(indexText)[0]?.name))+1)).padStart(2,'0')}</span><h3 className="mt-8 max-w-[75%] text-3xl font-bold uppercase text-primary">{previewSection||parseIndex(indexText)[0]?.name||'Divider title'}</h3><p className="absolute bottom-6 text-xs font-semibold text-muted-foreground">{selectedTemplateNames.divider}</p></div></div></div></div></div>
   <div className="rounded-lg border p-4"><div className="mb-3"><Label>Cover, index, divider &amp; brand design</Label><p className="text-xs text-muted-foreground">Choose reusable assets for this package. PQ does not use a cover template; all other choices are saved with the workspace.</p></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">{((packageType==='pq'?['index','divider','logo']:['cover','index','divider','logo']) as Array<'cover'|'index'|'divider'|'logo'>).map(type=><div key={type}><Label className="capitalize">{type} {type==='logo'?'image':'template'}</Label><select className="h-10 w-full rounded-md border bg-background px-3" value={templateIds[type]} onChange={e=>setTemplateIds(prev=>({...prev,[type]:e.target.value}))}><option value="">KINAIR standard</option>{(templates.data??[]).filter((t:any)=>t.template_type===type).map((t:any)=><option key={t.id} value={t.id}>{t.display_name}</option>)}</select></div>)}</div></div>
   <div className="rounded-lg border border-primary/30 bg-primary/5 p-4"><Label>AI material-schedule model selection</Label><p className="mb-3 text-xs text-muted-foreground">Upload PDF, image, Excel or CSV. AI can select multiple exact database models and multiple series; unavailable lines are never substituted silently.</p><Input type="file" accept=".pdf,image/png,image/jpeg,.xlsx,.xls,.csv" disabled={analyzeSchedule.isPending} onChange={uploadSchedule}/>{analyzeSchedule.isPending&&<p className="mt-2 flex items-center gap-2 text-sm"><Loader2 className="h-4 w-4 animate-spin"/>Reading schedule and matching models…</p>}{scheduleResult&&<div className="mt-3 rounded-md border bg-background p-3 text-sm"><b>{scheduleResult.matched_model_ids?.length||0} model(s) selected across {(scheduleResult.matched_series??[]).join(', ')||'no matched series'}</b>{scheduleResult.summary&&<p className="text-muted-foreground">{scheduleResult.summary}</p>}{scheduleResult.unmatched?.length>0&&<div className="mt-2 text-amber-700"><b>Needs review:</b><ul className="list-disc pl-5">{scheduleResult.unmatched.map((line:string,i:number)=><li key={i}>{line}</li>)}</ul></div>}</div>}</div>
   <div className="rounded-lg border p-4"><Label>Required product series</Label><p className="mb-3 text-xs text-muted-foreground">Select one or multiple series. Catalogue, O&amp;M Manual, Test Certificate and Approval Copies mapped to these series will be attached automatically.</p><div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{SERIES.map(s=><label key={s.name} className="flex items-center gap-2 rounded-md border p-2"><input type="checkbox" checked={chosenSeries.has(s.name)} onChange={()=>setChosenSeries(prev=>{const n=new Set(prev);n.has(s.name)?n.delete(s.name):n.add(s.name);return n})}/><span><b>{s.name}</b><small className="block text-muted-foreground">{s.brand} · {s.family}</small></span></label>)}</div></div>
   <div><Label>Products and models in this submittal</Label><div className="mt-2 grid gap-2 md:grid-cols-2">{(products.data??[]).flatMap((p:any)=>p.submittal_product_models.map((m:any)=><label key={m.id} className="flex items-center gap-3 rounded-md border p-3"><input type="checkbox" checked={selectedModels.has(m.id)} onChange={()=>toggle(m.id)}/><span><b>{m.code||m.name}</b><small className="block text-muted-foreground">{p.name} · {m.name}{modelMap.get(m.id)?.series?` · ${modelMap.get(m.id)?.series}`:''}</small></span></label>))}{!products.isLoading&&!(products.data??[]).some((p:any)=>p.submittal_product_models.length)&&<p className="text-sm text-muted-foreground">Add products and models in Product List first.</p>}</div></div>
   <div className="flex flex-wrap justify-end gap-2"><span className="mr-auto self-center text-xs text-muted-foreground">{saveWorkspace.isPending?'Saving changes…':packageId?'Autosave active':'Draft will be created when you upload or paste'}</span><Button variant="secondary" disabled={!packageId||saveWorkspace.isPending} onClick={()=>saveWorkspace.mutate()}>Save now</Button><Button variant="outline" disabled={!selectedPackage||revise.isPending} onClick={()=>revise.mutate()}><RotateCcw className="h-4 w-4"/>New revision</Button><Button variant="outline" disabled={build.isPending} onClick={()=>build.mutate()}><FileSearch className="h-4 w-4"/>Build entire submittal</Button><Button disabled={!packageId||!result||counts.missing>0||generate.isPending} onClick={()=>generate.mutate()}><UploadCloud className="h-4 w-4"/>Download final PDF</Button></div>
  </CardContent></Card>
  {packageId&&<SubmittalAttachments packageId={packageId} sectionNames={parseIndex(indexText).map(x=>x.name)}/>}
  <SubmittalTemplates onUploaded={(type,id)=>{if(type!=='stamp')setTemplateIds(prev=>({...prev,[type]:id}))}}/>
  <Card><CardHeader><CardTitle>Live assembly &amp; preflight</CardTitle><CardDescription>{result?`${counts.ready} ready · ${counts.missing} missing · ${counts.warning} warnings. Dividers and documents follow this exact order.`:'Run Validate & auto-build to match default and project documents.'}</CardDescription></CardHeader><CardContent className="space-y-2">{parseIndex(indexText).map((section,i)=>{const r=(result??[]).find((x:any)=>x.section===section.name);return <div key={section.id} className="flex gap-3 rounded-md border p-3">{!r?<span className="flex h-5 w-5 items-center justify-center rounded-full bg-muted text-xs">{i+1}</span>:r.state==='ready'?<CheckCircle2 className="h-5 w-5 text-emerald-600"/>:r.state==='missing'?<XCircle className="h-5 w-5 text-destructive"/>:<AlertTriangle className="h-5 w-5 text-amber-600"/>}<div><b>{i+1}. {section.name}</b><p className="text-xs text-muted-foreground">{r?.documents?.length?r.documents.join(' · '):r?'No matching document. Upload a project file or map a library default.':'Awaiting validation'}</p></div></div>})}</CardContent></Card>
 </div>
}
